// Owned bounded source observations; no sleep, public ticker or real retry timer.
package main
import("context";"encoding/json";"errors";"fmt";"os";"time"; b "github.com/cenkalti/backoff/v4")
var operationError=errors.New("owned-operation-error")
type clock struct{now time.Time;calls int}
func(c *clock)Now()time.Time{c.calls++;return c.now}
type policy struct{delay time.Duration;resets,nexts int;events *[]string}
func(p *policy)Reset(){p.resets++;*p.events=append(*p.events,"reset")}
func(p *policy)NextBackOff()time.Duration{p.nexts++;*p.events=append(*p.events,fmt.Sprint("next",p.nexts));return p.delay}
type timer struct{ch chan time.Time;starts,stops int;delays []int64;events *[]string;onStart func()}
func(t *timer)Start(d time.Duration){t.starts++;if t.starts>8{panic("owned-timer-bound")};t.delays=append(t.delays,int64(d));*t.events=append(*t.events,fmt.Sprint("timer-start",t.starts));if t.onStart!=nil{t.onStart();return};t.ch<-time.Unix(0,0)}
func(t *timer)C()<-chan time.Time{return t.ch}
func(t *timer)Stop(){t.stops++;*t.events=append(*t.events,"timer-stop")}
func newTimer(events *[]string)*timer{return &timer{ch:make(chan time.Time,1),events:events,delays:[]int64{}}}
func errorName(err error)string{if err==nil{return "none"};if err==context.Canceled{return "canceled"};if err==operationError{return "operation"};return "other:"+err.Error()}
func exponential(c *clock)*b.ExponentialBackOff{return &b.ExponentialBackOff{InitialInterval:10*time.Millisecond,RandomizationFactor:0,Multiplier:2,MaxInterval:60*time.Millisecond,MaxElapsedTime:time.Second,Stop:b.Stop,Clock:c}}
func retryCase(id string)(out map[string]any){out=map[string]any{};events:=[]string{};p:=&policy{delay:b.Stop,events:&events};t:=newTimer(&events);attempts,notifications:=0,0;var chosen b.BackOff=p;ctx,cancel:=context.WithCancel(context.Background());defer cancel();var c *clock
 defer func(){if v:=recover();v!=nil{out["panic"]=fmt.Sprint(v)};out["attempts"]=attempts;out["notify"]=notifications;out["timer_starts"]=t.starts;out["timer_stops"]=t.stops;out["delays_ns"]=t.delays;out["events"]=events;out["owned_policy_next_calls"]=p.nexts;out["owned_policy_resets"]=p.resets}()
 switch id{case"max-retries-zero":p.delay=0;chosen=b.WithMaxRetries(p,0);case"max-retries-two":p.delay=0;chosen=b.WithMaxRetries(p,2);case"fail-then-success","notify-order","notify-panic","timer-start-panic","cancel-during-timer":p.delay=0;case"canceled-success","canceled-error","canceled-permanent":cancel();chosen=b.WithContext(p,ctx);case"tries-outside-context":cancel();chosen=b.WithMaxRetries(b.WithContext(p,ctx),2);case"context-outside-tries":cancel();chosen=b.WithContext(b.WithMaxRetries(p,2),ctx);case"custom-positive-stop-retry":c=&clock{now:time.Unix(0,0)};e:=exponential(c);e.Stop=5*time.Millisecond;chosen=e}
 if id=="cancel-during-timer"{chosen=b.WithContext(p,ctx);t.onStart=cancel};if id=="timer-start-panic"{t.onStart=func(){panic("owned-timer")}}
 op:=func()error{attempts++;events=append(events,fmt.Sprint("operation",attempts));if attempts>5{return b.Permanent(errors.New("owned-operation-bound"))};switch id{case"stop-success","canceled-success":return nil;case"permanent-direct","canceled-permanent":return b.Permanent(operationError);case"permanent-wrapped":return fmt.Errorf("owned outer: %w",b.Permanent(operationError));case"permanent-nil":return b.Permanent(nil);case"operation-panic":panic("owned-operation");case"fail-then-success","notify-order":if attempts==2{return nil};case"custom-positive-stop-retry":if attempts==2{return nil};c.now=c.now.Add(2*time.Second)};return operationError}
 notify:=func(err error,d time.Duration){notifications++;events=append(events,fmt.Sprint("notify",notifications));if id=="notify-panic"{panic("owned-notify")}}
 var err error;if id=="default-timer-no-start"{out["custom_timer_used"]=false;err=b.RetryNotifyWithTimer(op,chosen,notify,nil)}else{err=b.RetryNotifyWithTimer(op,chosen,notify,t)};out["error"]=errorName(err);out["same_operation_error"]=err==operationError;return
}
func pureCase(id string)(out map[string]any){out=map[string]any{};defer func(){if v:=recover();v!=nil{out["panic"]=fmt.Sprint(v)}}();switch id{
case"context-rewrap":old,cancel:=context.WithCancel(context.Background());cancel();fresh:=context.Background();wrapped:=b.WithContext(b.WithContext(&b.ZeroBackOff{},old),fresh);out["new_context_used"]=wrapped.Context()==fresh;out["next_ns"]=int64(wrapped.NextBackOff());out["new_context_error"]=errorName(wrapped.Context().Err())
case"nil-context-panic":b.WithContext(&b.StopBackOff{},nil)
case"permanent-is-class":other:=errors.New("owned-other");outer:=b.Permanent(operationError);out["different_inner_error_wrapper_matches"]=errors.Is(outer,b.Permanent(other));out["is_inner"]=errors.Is(outer,operationError);out["is_other_inner"]=errors.Is(outer,other)
case"permanent-unwrap":out["unwrap_same_inner"]=errors.Unwrap(b.Permanent(operationError))==operationError;out["permanent_nil_is_nil"]=b.Permanent(nil)==nil
case"exp-default-stop","exp-custom-stop","exp-initial-over-cap","exp-growth","exp-elapsed-reset","exp-predicted-wait-cutoff":c:=&clock{now:time.Unix(0,0)};e:=exponential(c);switch id{case"exp-custom-stop":e.Stop=5*time.Millisecond;case"exp-initial-over-cap":e.InitialInterval=100*time.Millisecond;e.MaxInterval=50*time.Millisecond;e.MaxElapsedTime=0;case"exp-growth":e.MaxElapsedTime=0;case"exp-predicted-wait-cutoff":e.InitialInterval=100*time.Millisecond;e.MaxElapsedTime=50*time.Millisecond};e.Reset();switch id{case"exp-default-stop","exp-custom-stop":c.now=c.now.Add(2*time.Second);out["next_ns"]=int64(e.NextBackOff());case"exp-initial-over-cap","exp-growth":count:=2;if id=="exp-growth"{count=5};ds:=[]int64{};for n:=0;n<count;n++{ds=append(ds,int64(e.NextBackOff()))};out["durations_ns"]=ds;case"exp-elapsed-reset":c.now=c.now.Add(250*time.Millisecond);out["elapsed_before_reset_ns"]=int64(e.GetElapsedTime());e.Reset();out["elapsed_after_reset_ns"]=int64(e.GetElapsedTime());case"exp-predicted-wait-cutoff":out["elapsed_ns"]=int64(e.GetElapsedTime());out["next_ns"]=int64(e.NextBackOff())}
default:panic("unknown pure case")};return}
func main(){ids:=[]string{"stop-error","stop-success","max-retries-zero","max-retries-two","fail-then-success","permanent-direct","permanent-wrapped","permanent-nil","canceled-success","canceled-error","canceled-permanent","tries-outside-context","context-outside-tries","cancel-during-timer","notify-panic","operation-panic","timer-start-panic","context-rewrap","nil-context-panic","permanent-is-class","permanent-unwrap","exp-default-stop","exp-custom-stop","exp-initial-over-cap","exp-growth","exp-elapsed-reset","exp-predicted-wait-cutoff","notify-order","default-timer-no-start","custom-positive-stop-retry"};rows:=[]map[string]any{};for _,id:=range ids{var observed map[string]any;switch id{case"context-rewrap","nil-context-panic","permanent-is-class","permanent-unwrap","exp-default-stop","exp-custom-stop","exp-initial-over-cap","exp-growth","exp-elapsed-reset","exp-predicted-wait-cutoff":observed=pureCase(id);default:observed=retryCase(id)};rows=append(rows,map[string]any{"id":id,"observed":observed})};rows=append(rows,versionSpecific()...);if e:=json.NewEncoder(os.Stdout).Encode(rows);e!=nil{fmt.Fprintln(os.Stderr,e);os.Exit(1)}}
